/**
 * US-20 — parse_pharmacist_command.
 *
 * Authorization is two-layered:
 *   1. Telegram webhook secret (same contract as US-04/US-05/US-06/US-09):
 *      header X-Telegram-Bot-Api-Secret-Token compared against
 *      process.env.TELEGRAM_WEBHOOK_SECRET.
 *   2. The sender chat must be listed in process.env.TELEGRAM_PHARMACIST_CHAT_IDS
 *      (comma-separated chat_id list). Any other chat is dropped silently.
 *
 * Accepted commands (case-insensitive, optional "/" prefix and optional "#"):
 *   aprobar FAR-XXXX
 *   rechazar FAR-XXXX [motivo]
 *
 * Outputs ONE item { chat_id, command, codigo_far, motivo, text } or an EMPTY
 * array (unauthorized, non-text, or not a command). Never throws: the
 * immediate 200 was already returned by responseMode onReceived (RNF-01).
 */
function isAuthorized(headers, secret) {
  if (!headers || typeof headers !== 'object') return false;
  if (typeof secret !== 'string' || !secret) return false;
  const key = Object.keys(headers).find(
    (name) =>
      typeof name === 'string' &&
      name.toLowerCase() === 'x-telegram-bot-api-secret-token'
  );
  if (!key) return false;
  const value = headers[key];
  return typeof value === 'string' && value === secret;
}

/** True when chatId belongs to the comma-separated pharmacist list. */
function isPharmacist(chatId, list) {
  if (chatId === null || chatId === undefined) return false;
  const raw = typeof list === 'string' ? list : '';
  const ids = raw
    .split(',')
    .map(function (s) { return s.trim(); })
    .filter(function (s) { return s.length > 0; });
  return ids.length > 0 && ids.indexOf(String(chatId)) !== -1;
}

/** Sanitizes free text so it can travel inside JSON bodies and logs safely. */
function sanitizeMotivo(value) {
  const raw = typeof value === 'string' ? value : '';
  return raw
    .replace(/["\\\r\n\t]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 120);
}

/**
 * Parses "aprobar FAR-XXXX" / "rechazar FAR-XXXX [motivo]".
 * Returns { command, codigo_far, motivo } or null when the text is not a command.
 */
function parsePharmacistCommand(text) {
  if (typeof text !== 'string') return null;
  const m = /^\s*\/?\s*(aprobar|rechazar)\s+#?(FAR-\d{4})\b\s*(.*)$/i.exec(text);
  if (!m) return null;
  return {
    command: m[1].toLowerCase(),
    codigo_far: '#' + m[2].toUpperCase(),
    motivo: sanitizeMotivo(m[3])
  };
}

/**
 * Pure parser: one Telegram update -> ONE item or an EMPTY array
 * (unauthorized, not a pharmacist, non-text, or not a command).
 */
function parseTelegramUpdate(update, headers, secret, pharmacists) {
  if (!isAuthorized(headers, secret)) return [];
  if (!update || typeof update !== 'object') return [];
  const message = update.message;
  if (!message || typeof message !== 'object') return [];
  const chat =
    message.chat &&
    (typeof message.chat.id === 'string' || typeof message.chat.id === 'number')
      ? String(message.chat.id)
      : '';
  if (!chat) return [];
  if (!isPharmacist(chat, pharmacists)) return [];
  const text = typeof message.text === 'string' ? message.text.trim() : '';
  if (!text) return [];
  const parsed = parsePharmacistCommand(text);
  if (!parsed) return [];
  return [
    {
      json: {
        chat_id: chat,
        command: parsed.command,
        codigo_far: parsed.codigo_far,
        motivo: parsed.motivo,
        text: text
      }
    }
  ];
}

// --- n8n data assembly (guarded so the test harness can load the functions) ---
if (typeof $input !== 'undefined') {
  try {
    const items = $input.all();
    for (let i = 0; i < items.length; i++) {
      const item = items[i];
      const json = item && item.json ? item.json : item;
      const headers =
        json && json.headers && typeof json.headers === 'object' ? json.headers : {};
      const update = json && json.body && typeof json.body === 'object' ? json.body : json;
      const out = parseTelegramUpdate(
        update,
        headers,
        process.env.TELEGRAM_WEBHOOK_SECRET,
        process.env.TELEGRAM_PHARMACIST_CHAT_IDS
      );
      if (out.length) return out;
    }
  } catch (err) {
    return [];
  }
  return [];
}

/**
 * US-20 — evaluate_approval.
 *
 * Applies the pharmacist transition to ONE parsed command:
 *   aprobar  + RECETA_RECIBIDA -> EN_PREPARACION  (no stock effect)
 *   rechazar + RECETA_RECIBIDA -> RECHAZADO       (releases stock_reservado once)
 * Every other combination is INVALID and produces NO writes: the origin state
 * is the idempotency guard, so a repeated command can never release stock twice.
 *
 * The customer chat (ordenes.telefono) is notified on approval and rejection.
 */
const ESTADO_RECETA = 'RECETA_RECIBIDA';
const ESTADO_PREPARACION = 'EN_PREPARACION';
const ESTADO_RECHAZADO = 'RECHAZADO';
const ACCION_APROBADA = 'RECETA_APROBADA';
const ACCION_RECHAZADA = 'RECETA_RECHAZADA';

function normalize(s) {
  return String(s === null || s === undefined ? '' : s)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function rowJson(item) {
  return item && item.json ? item.json : item;
}

/** Canonical FAR code without the leading '#', uppercase. */
function codigoKey(value) {
  return String(value === null || value === undefined ? '' : value)
    .toUpperCase()
    .replace(/^#/, '')
    .trim();
}

function findOrderByCode(codigo, orderItems) {
  const key = codigoKey(codigo);
  if (!key) return null;
  const rows = (orderItems || [])
    .map(rowJson)
    .filter(function (r) { return r && typeof r === 'object'; });
  for (let i = 0; i < rows.length; i++) {
    if (codigoKey(rows[i].codigo_far) === key) return rows[i];
  }
  return null;
}

function findInventoryFor(medicamentoId, inventoryItems) {
  const key = normalize(medicamentoId);
  if (!key) return null;
  const rows = (inventoryItems || [])
    .map(rowJson)
    .filter(function (r) { return r && typeof r === 'object'; });
  for (let i = 0; i < rows.length; i++) {
    if (normalize(rows[i].medicamento_id) === key) return rows[i];
  }
  return null;
}

/**
 * Pure decision over the order state. Never throws.
 * Returns { decisionKey, estado_anterior, estado_nuevo, delta_reservado,
 *           pharmacist_message, customer_message }.
 */
function decideTransition(order, command, motivo, codigoRaw) {
  const codigo = order
    ? '#' + codigoKey(order.codigo_far)
    : (codigoRaw ? '#' + codigoKey(codigoRaw) : '#FAR-XXXX');
  const estado = order && order.estado ? String(order.estado) : '';
  const base = {
    decisionKey: 'INVALID',
    estado_anterior: '',
    estado_nuevo: '',
    delta_reservado: 0,
    pharmacist_message: '',
    customer_message: ''
  };
  if (!order) {
    base.pharmacist_message = 'No encontré el pedido ' + codigo + '.';
    return base;
  }
  const esAprobar = command === 'aprobar';
  const esRechazar = command === 'rechazar';
  if (!esAprobar && !esRechazar) {
    base.pharmacist_message =
      'Comando no reconocido. Usa "aprobar FAR-XXXX" o "rechazar FAR-XXXX [motivo]".';
    return base;
  }
  if (estado === ESTADO_RECETA) {
    if (esAprobar) {
      base.decisionKey = 'APPROVE';
      base.estado_anterior = ESTADO_RECETA;
      base.estado_nuevo = ESTADO_PREPARACION;
      base.pharmacist_message = 'Aprobado: ' + codigo + ' pasa a ' + ESTADO_PREPARACION + '.';
      base.customer_message = 'Tu pedido ' + codigo + ' fue aprobado y pasa a preparación.';
    } else {
      base.decisionKey = 'REJECT';
      base.estado_anterior = ESTADO_RECETA;
      base.estado_nuevo = ESTADO_RECHAZADO;
      base.delta_reservado = -Math.abs(Number(order.cantidad) || 0);
      base.pharmacist_message = 'Rechazado: ' + codigo + ' queda en ' + ESTADO_RECHAZADO + '.';
      base.customer_message =
        'Tu pedido ' + codigo + ' fue rechazado por el farmacéutico' +
        (motivo ? ': ' + motivo : '') +
        '. Puedes contactar a la farmacia si tienes dudas.';
    }
    return base;
  }
  if (esAprobar && estado === ESTADO_PREPARACION) {
    base.pharmacist_message =
      codigo + ' ya estaba aprobado (' + ESTADO_PREPARACION + '). No se aplicó ningún cambio.';
    return base;
  }
  if (esRechazar && estado === ESTADO_RECHAZADO) {
    base.pharmacist_message = codigo + ' ya estaba rechazado. No se aplicó ningún cambio.';
    return base;
  }
  base.pharmacist_message =
    codigo + ' no está en ' + ESTADO_RECETA +
    ' (estado actual: ' + (estado || 'desconocido') + '). No se aplicó ningún cambio.';
  return base;
}

/**
 * Inventory update payload for a rejection: stock_reservado decreases by the
 * order quantity and is clamped at 0 (never negative). Returns null when the
 * inventory row is missing (the caller warns instead of writing blindly).
 */
function buildInventoryUpdate(order, invRow, nowIso) {
  if (!order || !invRow) return null;
  const reserved = Number(invRow.stock_reservado);
  const cantidad = Math.abs(Number(order.cantidad) || 0);
  const current = isNaN(reserved) ? 0 : reserved;
  const expected = Math.max(0, current - cantidad);
  return {
    medicamento_id: order.medicamento_id,
    stock_real: Number(invRow.stock_real),
    stock_reservado: expected,
    ultima_actualizacion: nowIso || new Date().toISOString()
  };
}

/** Bitacora row with the extended audit columns (estado_anterior/estado_nuevo/actor). */
function buildBitacoraRow(order, decision, chatId, motivo, nowIso) {
  const codigo = codigoKey(order.codigo_far);
  const esRechazo = decision.decisionKey === 'REJECT';
  const detalle = esRechazo
    ? 'Rechazo farmacéutico vía Telegram; actor ' + chatId + '; motivo: ' + (motivo || 'sin motivo indicado')
    : 'Aprobación farmacéutica vía Telegram; actor ' + chatId;
  return {
    timestamp: nowIso || new Date().toISOString(),
    accion: esRechazo ? ACCION_RECHAZADA : ACCION_APROBADA,
    codigo_far: codigo,
    medicamento_id: order.medicamento_id,
    delta_reservado: decision.delta_reservado,
    detalle: detalle,
    estado_anterior: decision.estado_anterior,
    estado_nuevo: decision.estado_nuevo,
    actor: 'farmaceutico:' + chatId
  };
}

/**
 * Full payload for ONE parsed command, consumed by the write and reply nodes.
 * INVALID decisions carry no writes and no customer message.
 */
function evaluateApproval(parsed, orderItems, inventoryItems, nowIso) {
  if (!parsed || !parsed.chat_id || !parsed.command || !parsed.codigo_far) return null;
  const order = findOrderByCode(parsed.codigo_far, orderItems);
  const decision = decideTransition(order, parsed.command, parsed.motivo, parsed.codigo_far);
  const payload = {
    chat_id: String(parsed.chat_id),
    codigo_far: codigoKey(parsed.codigo_far),
    decision: decision.decisionKey,
    estado_anterior: decision.estado_anterior,
    estado_nuevo: decision.estado_nuevo,
    delta_reservado: decision.delta_reservado,
    update_stock: 'NO',
    inventory_update: null,
    bitacora_row: null,
    telefono:
      order && order.telefono !== null && order.telefono !== undefined
        ? String(order.telefono)
        : '',
    message_pharmacist: decision.pharmacist_message,
    message_customer: decision.customer_message || ''
  };
  if (decision.decisionKey === 'REJECT' && order) {
    const inv = findInventoryFor(order.medicamento_id, inventoryItems);
    const inventoryUpdate = buildInventoryUpdate(order, inv, nowIso);
    if (inventoryUpdate) {
      payload.update_stock = 'SI';
      payload.inventory_update = inventoryUpdate;
      payload.message_pharmacist +=
        ' Se liberó el stock reservado (' + Math.abs(Number(order.cantidad) || 0) + ').';
    } else {
      payload.message_pharmacist +=
        ' Advertencia: no se encontró fila de inventario; revisar manualmente.';
    }
  }
  if (decision.decisionKey === 'APPROVE' || decision.decisionKey === 'REJECT') {
    payload.bitacora_row = buildBitacoraRow(order, decision, parsed.chat_id, parsed.motivo, nowIso);
  }
  return payload;
}

// --- n8n data assembly (guarded so the test harness can load the functions) ---
if (typeof $ !== 'undefined' && typeof $input !== 'undefined') {
  let parsed = null;
  try {
    parsed = $('parse_pharmacist_command').first().json;
  } catch (err) {
    parsed = null;
  }
  if (!parsed) return [];
  const orderRows = $('read_ordenes').all();
  const inventoryRows = $('read_inventario').all();
  const payload = evaluateApproval(parsed, orderRows, inventoryRows, new Date().toISOString());
  if (!payload) return [];
  return [{ json: payload }];
}
